#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using LivingTable.Chess;
namespace LivingTable.Editor
{
 public static class ChessBuilder
 {
  static void Check(bool value,string message){if(!value)throw new Exception("CHESS TEST: "+message);}
  static long Perft(ChessPosition p,int depth){if(depth==0)return 1;long count=0;foreach(var move in p.LegalMoves())count+=Perft(p.After(move),depth-1);return count;}
  static ChessMove Move(ChessPosition p,int from,int to,int promotion=0)=>p.LegalMoves().Single(m=>m.From==from&&m.To==to&&m.Promotion==promotion);
  public static void RulesTests()
  {
   var initial=ChessPosition.Initial();Check(Perft(initial,1)==20,"Initial perft 1");Check(Perft(initial,2)==400,"Initial perft 2");Check(Perft(initial,3)==8902,"Initial perft 3");
   var kiwi=ChessPosition.FromFen("r3k2r/p1ppqpb1/bn2pnp1/3PN3/1p2P3/2N2Q1p/PPPBBPPP/R3K2R w KQkq - 0 1");Check(Perft(kiwi,1)==48,"Castling position perft 1");Check(Perft(kiwi,2)==2039,"Castling position perft 2");Check(Perft(kiwi,3)==97862,"Castling position perft 3");
   var castle=ChessPosition.FromFen("r3k2r/8/8/8/8/5r2/8/R3K2R w KQkq - 0 1");Check(!castle.LegalMoves().Any(m=>m.From==4&&m.To==6),"Cannot castle through check");Check(castle.LegalMoves().Any(m=>m.From==4&&m.To==2),"Other castle remains legal");var castled=castle.After(Move(castle,4,2));Check(castled.Board[3]==4&&castled.Board[0]==0&&castled.Board[2]==6,"Castling moves both pieces");
   var ep=ChessPosition.FromFen("4k3/8/8/3pP3/8/8/8/4K3 w - d6 0 1");var taken=ep.After(ep.LegalMoves().Single(m=>m.EnPassant));Check(taken.Board[35]==0&&taken.Board[43]==1,"En passant removes the passed pawn");var pinned=ChessPosition.FromFen("k3r3/8/8/3pP3/8/8/8/4K3 w - d6 0 1");Check(!pinned.LegalMoves().Any(m=>m.EnPassant),"En passant cannot expose own king");
   var promotion=ChessPosition.FromFen("4k3/P7/8/8/8/8/8/4K3 w - - 0 1");Check(promotion.LegalMoves().Count(m=>m.From==48&&m.To==56)==4,"All four promotions");
   var match=new ChessMatch();foreach(var pair in new[]{new[]{13,21},new[]{52,36},new[]{14,30},new[]{59,31}})Check(match.Play(Move(match.Position,pair[0],pair[1])),"Fool's mate sequence");Check(match.Result.Contains("Black wins"),"Checkmate ends play");Check(!match.Play(new ChessMove(8,16)),"Finished game rejects moves");match.Undo(1);Check(match.Result==""&&match.Position.Side==-1,"Undo restores unfinished state");
   Check(new ChessMatch(ChessPosition.FromFen("7k/5Q2/6K1/8/8/8/8/8 b - - 0 1")).Result.Contains("stalemate"),"Stalemate");Check(new ChessMatch(ChessPosition.FromFen("7k/8/8/8/8/8/8/K7 w - - 0 1")).Result.Contains("insufficient"),"Dead material");
   var draw=new ChessMatch(ChessPosition.FromFen("7k/8/8/8/8/8/8/KR6 w - - 100 51"));Check(draw.CanClaim&&draw.Result=="","50 moves is claimable, not auto-ended");Check(new ChessMatch(ChessPosition.FromFen("7k/8/8/8/8/8/8/KR6 w - - 150 76")).Result!="","75 moves auto draw");
   var repeats=new ChessMatch();for(int cycle=0;cycle<4;cycle++){foreach(var pair in new[]{new[]{1,18},new[]{57,42},new[]{18,1},new[]{42,57}})Check(repeats.Play(Move(repeats.Position,pair[0],pair[1])),"Repetition move");if(cycle==1)Check(repeats.CanClaim&&repeats.Result=="","Threefold claim");}Check(repeats.Result!="","Fivefold automatic draw");
   var mate=ChessPosition.FromFen("7k/5Q2/6K1/8/8/8/8/8 w - - 0 1");var ai=ChessAi.Choose(mate,2000,2);Check(new ChessMatch(mate.After(ai)).Result.Contains("checkmate"),"AI finds mate in one");Check(initial.LegalMoves().Contains(ChessAi.Choose(initial,200,3)),"AI budget always returns a legal move");
   var before=Enumerable.Range(0,64).Select(i=>new float[12]).ToArray();foreach(var row in before)row[0]=1;var after=before.Select(a=>(float[])a.Clone()).ToArray();foreach(int s in new[]{12,28}){after[s][0]=0;after[s][1]=1;}var inferred=ChessPhysicalVision.Infer(initial,before,after);Check(inferred.HasValue&&inferred.Value.From==12&&inferred.Value.To==28,"Camera infers unique legal e2-e4");after[10][0]=0;after[10][1]=1;Check(!ChessPhysicalVision.Infer(initial,before,after).HasValue,"Occlusion / extra changed squares rejected");Check(!ChessPhysicalVision.Infer(initial,before,before).HasValue,"Still board does not advance");
   var castleBefore=before.Select(a=>(float[])a.Clone()).ToArray();var castleAfter=before.Select(a=>(float[])a.Clone()).ToArray();var move=Move(castle,4,2);foreach(int square in ChessPhysicalVision.ChangedSquares(castle,move)){castleAfter[square][0]=0;castleAfter[square][1]=1;}Check(ChessPhysicalVision.Infer(castle,castleBefore,castleAfter).HasValue,"Physical castling requires four changed cells");castleAfter[0]=(float[])castleBefore[0].Clone();Check(!ChessPhysicalVision.Infer(castle,castleBefore,castleAfter).HasValue,"Partial physical castle waits");
   Directory.CreateDirectory("Logs");File.WriteAllText("Logs/Chess-rules-tests.txt","PASS: initial perft 20/400/8902; Kiwipete 48/2039/97862; castling; pinned en passant; promotion; checkmate; stalemate; material; repetition; 50/75-move distinction; AI legality and mate; physical change inference/rejection.\nPhysical camera accuracy still requires a real board test.\n");Debug.Log("CHESS_RULES_TESTS_PASSED");
  }
  public static void PrepareAndTest(){RulesTests();EditorSceneManager.OpenScene("Assets/LivingTable/CandyLand/CandyLandDesktop.unity");SessionState.SetBool("ChessSmoke",true);EditorApplication.EnterPlaymode();}
  static int stage;static double deadline;static ChessTable table;
  [InitializeOnLoadMethod]static void Resume(){if(!SessionState.GetBool("ChessSmoke",false))return;stage=0;deadline=EditorApplication.timeSinceStartup+75;EditorApplication.update+=Tick;}
  static void Tick(){try{if(EditorApplication.timeSinceStartup>deadline)throw new Exception("Chess scene timeout");if(!EditorApplication.isPlaying||EditorApplication.isCompiling)return;var experience=UnityEngine.Object.FindFirstObjectByType<LivingTableExperience>();if(experience==null)return;
   if(stage==0){var candy=UnityEngine.Object.FindFirstObjectByType<CandyLand.CandyTable>();if(candy==null||candy.Data==null)return;Check(candy.GetComponentsInChildren<TableButtonVisual>().Any(b=>b.name=="CHESS button"),"Chess is offered in existing game setup");experience.SelectChess();table=UnityEngine.Object.FindFirstObjectByType<ChessTable>();Check(table!=null&&!candy.enabled,"Switch stops Candy input");Check(table.VisiblePieceCount==32,"32 preview pieces");table.Configure(false,false,1);table.StartGame();table.SelectSquare(12);table.SelectSquare(28);Check(table.Match.Position.Board[28]==1&&table.Match.Position.Board[12]==0,"Player e2-e4");stage=1;}
   else if(stage==1){if(table.Busy||table.Match.Position.Ply<2)return;Check(table.Match.Position.Side==1&&table.VisiblePieceCount==32,"AI reply and piece count");SaveView();var point=table.PieceWorldPosition(6)+Vector3.up*.025f;Check(table.BeginGrab(71,point),"Pinch a knight");table.UpdateGrab(71,table.SquareWorld(21)+Vector3.up*.04f,true);Check(table.AwaitingDone&&table.ConfirmPlayerMove()&&table.Match.Position.Board[21]==2,"Done confirms pinched knight move");stage=2;}
   else if(stage==2){if(table.Busy)return;table.NewGame();table.Configure(true,true,1);table.StartGame();Check(!table.Playing,"Physical mode needs alignment");table.TouchWorld(table.transform.TransformPoint(new Vector3(-.28f,0,-.28f))); // no alignment action yet
    var button=table.GetComponentsInChildren<TableButtonVisual>().First(b=>b.name=="ALIGN BOARD button");table.TouchWorld(button.transform.position);stage=3;}
   else if(stage==3){var p=table.transform.position;table.TouchWorld(p+new Vector3(-.28f,0,-.28f));table.TouchWorld(p+new Vector3(.28f,0,-.28f));if(!table.Aligned)return;table.StartGame();Check(table.Playing&&table.VisiblePieceCount==0,"Physical pieces are not duplicated");int version=table.Version;var move=Move(table.Match.Position,12,28);Check(!table.ApplyCameraMove(move,version-1),"Stale camera frame rejected");Check(table.ApplyCameraMove(move,version),"Camera advances a legal physical move");Check(!table.ApplyCameraMove(move,version),"Duplicate frame rejected");table.ToggleManual();table.SelectSquare(52);table.SelectSquare(36);Check(table.Match.Position.Ply==2,"Manual physical fallback");table.NewGame();experience.SelectCandy();Check(!experience.ChessActive&&UnityEngine.Object.FindFirstObjectByType<CandyLand.CandyTable>().enabled,"Return to Candy Land");Finish(0,"CHESS_SCENE_TESTS_PASSED");}
  }catch(Exception e){Finish(1,e.ToString());}}
  static void SaveView(){var camera=Camera.main;camera.transform.position=new Vector3(.1f,1.55f,-.78f);camera.transform.LookAt(new Vector3(0,.8f,-.02f));table.SendMessage("Update");foreach(var panel in table.GetComponentsInChildren<TableFacingPanel>())panel.FaceViewer();var rt=new RenderTexture(1600,1200,24);camera.targetTexture=rt;camera.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var image=new Texture2D(1600,1200,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1600,1200),0,0);image.Apply();File.WriteAllBytes("Logs/Chess-MVP.png",image.EncodeToPNG());RenderTexture.active=previous;camera.targetTexture=null;UnityEngine.Object.Destroy(rt);UnityEngine.Object.Destroy(image);}
  static void Finish(int code,string text){SessionState.SetBool("ChessSmoke",false);EditorApplication.update-=Tick;if(code==0)Debug.Log(text);else Debug.LogError(text);EditorApplication.Exit(code);}
 }
}
#endif
